    $('search').oninput=()=>this.renderLibrary();click('back-library',()=>this.backLibrary());click('editor-more',()=>this.noteMenu(this.active!));click('more-close',()=>$<HTMLDialogElement>('more-dialog').close());
    click('toolbox-open',()=>this.openPanel('tools'));click('drafts-open',()=>this.openPanel('drafts'));click('pages-open',()=>this.openPanel('pages'));click('panel-close',()=>this.closePanel());
    for(const t of ['pen','eraser','pan'] as InkTool[])click('tool-'+t,()=>this.setTool(t));click('undo',()=>this.undo());click('redo',()=>this.redo());
    $<HTMLInputElement>('ink-color').oninput=()=>{this.canvas.color=$<HTMLInputElement>('ink-color').value;void this.setTool(this.tool);};$<HTMLSelectElement>('pen-width').onchange=()=>{this.canvas.width=Number($<HTMLSelectElement>('pen-width').value);void this.setTool(this.tool);};
    $<HTMLInputElement>('finger-writing').onchange=()=>{this.canvas.fingerWriting=$<HTMLInputElement>('finger-writing').checked;if(this.session?.ready)void this.session.request('setFingerWriting',{enabled:this.canvas.fingerWriting});};
    click('add-page',()=>this.addHandwrittenPage());click('prev-page',()=>this.neighbor(-1));click('next-page',()=>this.neighbor(1));click('zoom-fit',()=>{if(this.session?.ready&&this.inkMode==='butterfly')return this.session.request('setView',{x:0,y:0,zoom:1});this.canvas.fit();});
    click('recognize',()=>this.prepareRecognition('formula'));click('selection-cancel',()=>this.cancelSelection());click('select-all',()=>this.canvas.selectAll());click('placement-cancel',()=>this.cancelPlacement());
    click('retry-save',()=>this.flush());click('emergency-export',()=>this.exportCurrentMemory());
    for(const id of ['recognition-close','recognition-cancel'])click(id,()=>{this.approval=null;$<HTMLDialogElement>('recognition-dialog').close();if(id==='recognition-cancel')return this.cancelSelection();});click('recognition-configure',()=>{$<HTMLDialogElement>('recognition-dialog').close();this.openSettings(true);});
    click('recognition-submit',async()=>{const f=this.approval;if(!f)return;this.approval=null;$<HTMLButtonElement>('recognition-submit').disabled=true;try{await f();$<HTMLDialogElement>('recognition-dialog').close();}finally{$<HTMLButtonElement>('recognition-submit').disabled=false;}});
    click('settings-close',()=>$<HTMLDialogElement>('settings-dialog').close());$('settings-form').onsubmit=e=>{e.preventDefault();void this.action(()=>this.applySettings());};click('health-check',()=>this.checkService());click('pair-local',()=>this.pairLocal());
    $<HTMLInputElement>('note-title').onchange=()=>{if(this.active){this.active.title=$<HTMLInputElement>('note-title').value.trim()||'未命名笔记';this.scheduleSave(false);}};
    click('advanced-close',()=>$<HTMLDialogElement>('advanced-dialog').close());$<HTMLInputElement>('restore-file').onchange=()=>void this.action(()=>this.importBackup());
    document.addEventListener('keydown',e=>{if((e.target as HTMLElement)?.matches('input,textarea,select,[contenteditable="true"]'))return;if(e.key==='Escape'){if(this.placement)this.cancelPlacement();else if(this.selecting)void this.cancelSelection();else this.closePanel();}if(!(e.ctrlKey||e.metaKey)||this.view!=='editor')return;if(e.key==='z'){e.preventDefault();void this.action(()=>e.shiftKey?this.redo():this.undo());}if(e.key==='y'){e.preventDefault();void this.action(()=>this.redo());}if(e.key==='s'){e.preventDefault();void this.action(async()=>{await this.flush();this.notify('已保存到本机');});}});
    window.addEventListener('pagehide',()=>{this.canvas.finish();void this.flush();});
    document.addEventListener('visibilitychange',()=>{if(document.hidden){this.canvas.finish();void this.flush();}else void this.tasks.resumeAll();});
    $<HTMLDialogElement>('recognition-dialog').oncancel=()=>{this.approval=null;};
    $('butterfly-placement').onclick=e=>void this.action(async()=>{if(!this.placement||!this.frame)return;const r=this.frame.getBoundingClientRect(),v=this.nativePlacementView;await this.confirmPlacement({x:((e as MouseEvent).clientX-r.left)/v.zoom+v.x,y:((e as MouseEvent).clientY-r.top)/v.zoom+v.y});});
    $('butterfly-placement').onpointermove=e=>{const ghost=$('native-placement-preview');if(!ghost)return;const r=$('butterfly-placement').getBoundingClientRect();ghost.style.left=(e.clientX-r.left)+'px';ghost.style.top=(e.clientY-r.top)+'px';};
